import {
  useState,
  useContext
} from "react";

import {
  useNavigate
} from "react-router-dom";

import api from "../api/axios";

import {
  AuthContext
} from "../context/AuthContext";

const Login = () => {

  const navigate =
    useNavigate();

  const {
    login
  } = useContext(
    AuthContext
  );

  const [formData,
    setFormData
  ] = useState({
    email: "",
    password: ""
  });

  const handleChange = (
    e
  ) => {

    setFormData({
      ...formData,
      [e.target.name]:
      e.target.value
    });

  };

  const handleSubmit =
    async (e) => {

    e.preventDefault();

    try {

      const res =
        await api.post(
          "/auth/login",
          formData
        );

      login(
        res.data.user,
        res.data.token
      );

      const role =
        res.data.user.role;

      if (
        role === "ADMIN"
      ) {
        navigate("/admin");
      }

      else if (
        role ===
        "STORE_OWNER"
      ) {
        navigate("/owner");
      }

      else {
        navigate("/stores");
      }

    } catch (error) {

      alert(
        error.response?.data?.message ||
        "Login Failed"
      );

    }
  };

  return (
    <div>

      <h2>Login</h2>

      <form
        onSubmit={
          handleSubmit
        }
      >

        <input
          type="email"
          name="email"
          placeholder="Email"
          onChange={
            handleChange
          }
          required
        />

        <br /><br />

        <input
          type="password"
          name="password"
          placeholder="Password"
          onChange={
            handleChange
          }
          required
        />

        <br /><br />

        <button>
          Login
        </button>

      </form>

    </div>
  );
};

export default Login;
